sys_script_include.script:
function BusinessProcessPrepareImplementation(business_process, vApp)
{
	if (BusinessProcessValidate(business_process,false) == false)
	{
		return false;
	}

	// App context (optional)

	var grApp = null;
	grApp = GetAppRecord(vApp);

	// Class

	var strClassName = GetStringValue(business_process.class_name);
	if (IsValidJavaScriptIdentifier(strClassName) == false)
	{
		strClassName = MakeJavaScriptIdentifier(business_process.name + ' Process');
		business_process.class_name = strClassName;
	}

	// Table
	var strTableName = '';
	if (IsValidRecord(grApp) == true)
	{
		strTableName = MakeTableName(grApp,business_process.id);
	}


	// Identify state values from existing sys_choice records
	var aStates = GetValue(business_process,'_states');
	if (IsValidRecord(grApp) == true)
	{
		var grChoiceSet = RecordQuery('sys_choice_set',
			{
				sys_scope: grApp.sys_id,
				name: strTableName,
				element: 'state'
			});

		if (IsValidRecord(grChoiceSet) == true)
		{
			for (var nState = 0; nState < aStates.length; nState++)
			{
				var state = aStates[nState];
				var nStateValue = GetValue(state,'value');
				var strStateName = GetStringValue(GetValue(state,'name'));
				if (nStateValue === null)
				{
					var grChoice = RecordQuery(
						'sys_choice',
						{
							name: strTableName,
							element: 'state',
							language: 'en',
							label: strStateName
						});
					if (IsValidRecord(grChoice) == true)
					{
						aStates[nState].value = GetIntegerValue(grChoice.value);
					}
				}
			}
		}
	}

	// Set values for states
	var strInitialStateId = business_process.initial_state;
	var aEndStateIds = GetArrayValue(business_process.end_states);
	var nIndexRegular = 0;
	var nIndexEnd = 0;
	for (var nState = 0; nState < aStates.length; nState++)
	{
		var state = aStates[nState];
		var nStateValue = GetValue(state,'value');
		if (nStateValue === null)
		{
			var nValue = 0;
			var strId = GetValue(state,'id');
			if (strId == strInitialStateId)
			{
				nValue = 1;
			}
			else
			{
				if (ArrayValueExists(aEndStateIds,strId) == true)
				{
					nValue = 10000 + nIndexEnd * 100;
					nIndexEnd++;
				}
				else
				{
					nIndexRegular++;
					nValue = nIndexRegular * 100;
				}
			}
			aStates[nState].value = nValue;
		}
	}
	business_process._states = aStates;


	return business_process;
}
